using VisualRelay.Core.Configuration;
using VisualRelay.Core.Costs;
using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

public sealed class BackendConfigGeneratorAliasConsistencyTests
{
    // ── Cross-file alias-name consistency ────────────────────────────────

    /// <summary>
    /// The balanced/cheap tier-alias names must be identical across the
    /// three sites that define them:
    ///   <see cref="BackendConfigGenerator"/>.<c>Chains</c>.Keys,
    ///   <see cref="RelayPricing"/>.<c>Default</c>.Keys, and
    ///   <see cref="SwivalProfileSession"/>.<c>DefaultToml</c> model values.
    /// If this test fails, a tier alias was renamed in one place but not
    /// the others — update all three together.
    /// </summary>
    [Fact]
    public void TierAliasNames_AreConsistentAcrossBackendConfigPricingAndSwivalProfile()
    {
        // 1. Extract tier-alias names from BackendConfigGenerator.Chains.
        var backendAliases = BackendConfigGenerator.Chains.Keys.ToHashSet(StringComparer.Ordinal);

        // 2. Extract tier-alias names from RelayPricing.Default.
        var pricingAliases = RelayPricing.Default.Keys.ToHashSet(StringComparer.Ordinal);

        // 3. Parse SwivalProfileSession.DefaultToml for model values of
        //    the [profiles.balanced] and [profiles.cheap] sections.
        var swivalModelValues = BackendConfigGeneratorTestHelpers.ParseSwivalProfileModelValues(
            SwivalProfileSession.DefaultToml);

        // The balanced and cheap model values are the canonical tier names.
        var balancedTier = swivalModelValues["balanced"];
        var cheapTier = swivalModelValues["cheap"];

        // Vestigial "-kimi" suffix must not appear in the tier names.
        Assert.DoesNotContain("-kimi", balancedTier, StringComparison.Ordinal);
        Assert.DoesNotContain("-kimi", cheapTier, StringComparison.Ordinal);
        Assert.Equal("balanced", balancedTier);
        Assert.Equal("cheap", cheapTier);

        // The canonical tier names must be present in all three sources.
        Assert.Contains(balancedTier, backendAliases);
        Assert.Contains(cheapTier, backendAliases);
        Assert.Contains(balancedTier, pricingAliases);
        Assert.Contains(cheapTier, pricingAliases);
    }
}

using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

/// <summary>
/// Vision-tier routing tests (2026-07-07 fix).  Pins the upstream model
/// strings in the template and asserts the all-vision-capable invariant
/// for the chain and selectable lists.
/// </summary>
public sealed class BackendConfigGeneratorVisionTierTests
{
    /// <summary>Models known to be vision-capable in the current config.</summary>
    private static readonly HashSet<string> VisionCapableModels =
        ["hf-qwen3-vl-235b", "hf-qwen3-vl-30b"];

    // ── 1. Template model strings ────────────────────────────────────────

    [Fact]
    public void VisionTemplate_Vl235bModelString_IsAutoRouted()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);

        // The 235B entry must use the auto-routed path (no pinned provider
        // like /novita/ or /deepinfra/ in the segment).
        Assert.Contains(
            "model: huggingface/Qwen/Qwen3-VL-235B-A22B-Instruct",
            yaml, StringComparison.Ordinal);
        Assert.DoesNotContain("huggingface/novita/Qwen/Qwen3-VL-235B", yaml, StringComparison.Ordinal);
        Assert.DoesNotContain("huggingface/deepinfra/Qwen/Qwen3-VL-235B", yaml, StringComparison.Ordinal);
    }

    [Fact]
    public void VisionTemplate_Vl30bModelString_IsAutoRouted()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);

        Assert.Contains(
            "model: huggingface/Qwen/Qwen3-VL-30B-A3B-Instruct",
            yaml, StringComparison.Ordinal);
        Assert.DoesNotContain("huggingface/novita/Qwen/Qwen3-VL-30B", yaml, StringComparison.Ordinal);
        Assert.DoesNotContain("huggingface/deepinfra/Qwen/Qwen3-VL-30B", yaml, StringComparison.Ordinal);
    }

    // ── 3. Chain exact membership ────────────────────────────────────────

    [Fact]
    public void VisionChain_HasExactMembership()
    {
        Assert.True(BackendConfigGenerator.Chains.TryGetValue("vision", out var chain));
        var models = chain.Select(c => c.Model).ToHashSet();

        Assert.Equal(VisionCapableModels, models);

        // Every model in the vision chain requires HF_TOKEN (the sole key
        // gating HF Inference Providers).
        Assert.All(chain, c => Assert.Equal("HF_TOKEN", c.RequiredKey));
    }

    // ── 4. Selectable exact membership ────────────────────────────────────

    [Fact]
    public void VisionSelectable_HasExactMembership()
    {
        Assert.True(
            BackendConfigGenerator.SelectableModelsByTier.TryGetValue("vision", out var selectable));

        Assert.Equal(VisionCapableModels, selectable.ToHashSet());

        // No text models (kimi-k2 was the offender).
        Assert.DoesNotContain("kimi-k2", selectable);
    }

    // ── 5. Generated vision fallback chain — vision-only ──────────────────

    [Fact]
    public void VisionFallbackChain_OnlyVisionModels_WithHfToken()
    {
        var present = new HashSet<string> { "HF_TOKEN" };
        var aliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(present);
        var fallbacks = BackendConfigGeneratorTestHelpers.GeneratedFallbacks(present);

        Assert.True(aliases.ContainsKey("vision"));
        Assert.Equal("hf-qwen3-vl-235b", aliases["vision"]);

        Assert.True(fallbacks.ContainsKey("vision"));
        var chain = fallbacks["vision"];

        // Every model in the fallback chain must be vision-capable.
        Assert.All(chain, m => Assert.Contains(m, VisionCapableModels));

        // Must NOT contain any non-vision model or the fallback alias.
        Assert.DoesNotContain("kimi-k2", chain);
        Assert.DoesNotContain("fallback", chain);
        Assert.DoesNotContain("hf-qwen3-coder-next", chain);
        Assert.DoesNotContain("deepseek-v4-pro", chain);
        Assert.DoesNotContain("deepseek-v4-flash", chain);
        Assert.DoesNotContain("glm-5.2", chain);
    }

    // ── 6. Vision alias resolves to 235B primary ──────────────────────────

    [Fact]
    public void VisionAlias_IsHfQwen3Vl235b_WhenHfTokenPresent()
    {
        var present = new HashSet<string> { "HF_TOKEN" };
        var aliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(present);

        Assert.Equal("hf-qwen3-vl-235b", aliases["vision"]);

        // Also true with additional keys present.
        var trio = new HashSet<string> { "HF_TOKEN", "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY" };
        var trioAliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(trio);
        Assert.Equal("hf-qwen3-vl-235b", trioAliases["vision"]);
    }

    // ── 7. Vision tier absent when no HF_TOKEN ────────────────────────────

    [Fact]
    public void VisionTier_AbsentWhenNoHfToken()
    {
        // No HF_TOKEN → both VL models unavailable → vision tier skipped
        // entirely, so a vision request produces a "model not found" error
        // instead of a silent text-model answer.
        var noKeys = new HashSet<string>();
        var noKeysAliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(noKeys);
        Assert.False(noKeysAliases.ContainsKey("vision"));

        var dsOnly = new HashSet<string> { "DEEPSEEK_API_KEY" };
        var dsAliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(dsOnly);
        Assert.False(dsAliases.ContainsKey("vision"));

        var moonshotOnly = new HashSet<string> { "MOONSHOT_API_KEY" };
        var msAliases = BackendConfigGeneratorTestHelpers.GeneratedAliases(moonshotOnly);
        Assert.False(msAliases.ContainsKey("vision"));
    }
}

using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

public sealed class BackendConfigGeneratorPerModelTimeoutTests
{
    // ── 8. Per-model hard-timeout ceilings ───────────────────────────────

    /// <summary>
    /// Every model in the template must carry an explicit per-model
    /// <c>timeout:</c> so no request can hang indefinitely on a byte-0
    /// upstream stall (the global request_timeout alone proved insufficient
    /// for the 2026-06-10 wedge).
    /// </summary>
    [Fact]
    public void PerModelTimeout_AllTenModelsHaveExplicitCeiling()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        string[] allModels =
        [
            "glm-5.2",
            "kimi-k2",
            "deepseek-v4-pro",
            "deepseek-v4-flash",
            "hf-qwen3-coder-next",
            "hf-qwen3-vl-235b",
            "hf-qwen3-vl-30b",
            "claude-opus-1m",
            "claude-sonnet",
            "gpt-5",
        ];

        foreach (var model in allModels)
            Assert.True(timeouts.ContainsKey(model),
                $"model '{model}' must have an explicit per-model timeout");
    }

    [Fact]
    public void PerModelTimeout_FrontierKimiK2Has480s()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        Assert.True(timeouts.TryGetValue("kimi-k2", out var t),
            "kimi-k2 must have a per-model timeout");
        // 480s (8 min) > 412s observed worst-case healthy Review,
        // far below the 40-min stage cap.
        Assert.Equal(480, t);
    }

    [Fact]
    public void PerModelTimeout_FrontierGlm52Has480s()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        Assert.True(timeouts.TryGetValue("glm-5.2", out var t),
            "glm-5.2 must have a per-model timeout");
        // 480s (8 min) — same frontier ceiling as kimi-k2; > 412s observed
        // worst-case healthy Review, far below the 40-min stage cap.
        Assert.Equal(480, t);
    }

    [Fact]
    public void PerModelTimeout_DeepSeekModelsKeep75s()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        // 75s is below the relay's first-output watchdog (90s/120s) so a
        // hung DeepSeek call hits this Timeout first → fallback engages.
        Assert.Equal(75, timeouts["deepseek-v4-pro"]);
        Assert.Equal(75, timeouts["deepseek-v4-flash"]);
    }

    [Fact]
    public void [ENCRYPTED:fastly]hplacdq2g-x9UN73O-V3LFKN9VUnHorh()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        // 120s (2 min) — generous for HF inference; cross-provider floor.
        Assert.Equal(120, timeouts["hf-qwen3-coder-next"]);
        Assert.Equal(120, timeouts["hf-qwen3-vl-235b"]);
        Assert.Equal(120, timeouts["hf-qwen3-vl-30b"]);
    }

    [Fact]
    public void PerModelTimeout_ClaudeAndOpenAiHave300s()
    {
        var yaml = File.ReadAllText(BackendConfigGeneratorTestHelpers.TemplatePath);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        // 300s (5 min) matches the global request_timeout; Claude/OpenAI
        // are fast and this ceiling is a safety net, not a latency budget.
        Assert.Equal(300, timeouts["claude-opus-1m"]);
        Assert.Equal(300, timeouts["claude-sonnet"]);
        Assert.Equal(300, timeouts["gpt-5"]);
    }

    /// <summary>
    /// The generator passes <c>model_list</c> through verbatim, so every
    /// per-model timeout in the template must survive into the generated
    /// YAML that the backend actually runs.
    /// </summary>
    [Fact]
    public void PerModelTimeout_GeneratedYamlPreservesAllCeilings()
    {
        var present = new HashSet<string>
        {
            "HF_TOKEN", "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY",
            "ANTHROPIC_API_KEY", "OPENAI_API_KEY",
        };
        var (yaml, _) = BackendConfigGeneratorTestHelpers.Generate(present);
        var timeouts = BackendConfigGeneratorTestHelpers.ParseModelTimeouts(yaml);

        Assert.Equal(480, timeouts["glm-5.2"]);
        Assert.Equal(480, timeouts["kimi-k2"]);
        Assert.Equal(75, timeouts["deepseek-v4-pro"]);
        Assert.Equal(75, timeouts["deepseek-v4-flash"]);
        Assert.Equal(120, timeouts["hf-qwen3-coder-next"]);
        Assert.Equal(120, timeouts["hf-qwen3-vl-235b"]);
        Assert.Equal(120, timeouts["hf-qwen3-vl-30b"]);
        Assert.Equal(300, timeouts["claude-opus-1m"]);
        Assert.Equal(300, timeouts["claude-sonnet"]);
        Assert.Equal(300, timeouts["gpt-5"]);
    }
}

